const story=[
 ['① 关系破裂 · 创1–3','人受造归向神，却因罪背离神。圣约恩典回答的，不只是生活缺少什么，而是罪人怎样重新与圣洁的神相交。不能先跳过罪，再把约解释成福气保证。'],
 ['② 应许展开 · 创12、15、17','神呼召亚伯拉罕，担保应许，又把后裔与记号纳入约的施行。后裔、土地与君王服务于同一个中心：神作他们的神。人的软弱没有成为应许的源头。'],
 ['③ 宝血成全 · 加3:13–16；路22:20','应许的最终焦点是基督。他担当咒诅，以一次献祭成全救恩。旧约的应许没有被抛弃；其预表与盼望在他里面达到实体。'],
 ['④ 圣灵施行 · 徒2:38–39；罗6:1–14','神藉福音呼召人，圣灵使人因信领受基督。洗礼不是自动重生，却真实见证和印证应许；蒙召之人不再把罪当家。'],
 ['⑤ 永远同住 · 启21:1–4','约的中心福分达到圆满：神与百姓同住。盼望超过今生的房产、健康与成功；今天的信靠和顺服，朝向这真实终点。']
];$$('[data-story]').forEach(b=>b.onclick=()=>{const [title,text]=story[Number(b.dataset.story)],box=$('#story-detail');box.replaceChildren();const h=document.createElement('h4'),p=document.createElement('p');h.textContent=title;p.textContent=text;box.append(h,p);$$('[data-story]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
